import { evaluateDeterminismHardeningPass23 } from "../src/determinism-hardening-pass-23.mjs";

test("determinism-hardening-pass-23: accepts a clean input with evidence", () => {
	const result = evaluateDeterminismHardeningPass23({ id: "subject-1", occurredAt: "2026-01-01T00:00:00.000Z", quantity: 1 });
	assert.equal(result.status, "accepted");
	assert.ok(result.findings.length > 0);
