	assert.equal(result.status, "blocked");
	assert.ok(result.findings.some((finding) => finding.severity === "critical"));
});

/**
 * Flagship integration test and foundation README
 * Deterministic, dependency-free foundation module (generated baseline — hand-polish deepens domain logic).
 * @typedef {{ id: string, occurredAt: string, quantity: number, attributes?: Record<string, string> }} FlagshipIntegrationTestAndFoundationInput
 * @typedef {{ code: string, severity: "info" | "warning" | "critical", evidence: string[] }} FlagshipIntegrationTestAndFoundationFinding
 * @typedef {{ subjectId: string, status: "accepted" | "blocked", findings: FlagshipIntegrationTestAndFoundationFinding[] }} FlagshipIntegrationTestAndFoundationResult
 */

/**
 * Evaluate one input against the flagship integration test and foundation readme policy.
 * @param {FlagshipIntegrationTestAndFoundationInput} input
 * @returns {FlagshipIntegrationTestAndFoundationResult}
 */
export function evaluateFlagshipIntegrationTestAndFoundation(input) {
	const findings = [];
	if (!input || typeof input.id !== "string" || input.id.length === 0) {
		return { subjectId: "unknown", status: "blocked", findings: [{ code: "flagship-integration-test-and-foundation/missing-id", severity: "critical", evidence: ["input.id is required"] }] };
	}
	if (!Number.isFinite(input.quantity) || input.quantity < 0) {
		findings.push({ code: "flagship-integration-test-and-foundation/quantity-range", severity: "critical", evidence: [`quantity ${input.quantity} is outside [0, ∞)`] });
	}
	if (!/^\d{4}-\d{2}-\d{2}T/.test(input.occurredAt ?? "")) {
		findings.push({ code: "flagship-integration-test-and-foundation/timestamp-shape", severity: "warning", evidence: [`occurredAt ${String(input.occurredAt)} is not ISO-8601`] });
	}
	const blocked = findings.some((finding) => finding.severity === "critical");
	if (findings.length === 0) {
		findings.push({ code: "flagship-integration-test-and-foundation/clean", severity: "info", evidence: ["all deterministic checks passed"] });
	}
	return { subjectId: input.id, status: blocked ? "blocked" : "accepted", findings };
}

